INSERT INTO trucker.store_pg
  (id, store_id, rec_start_date, rec_end_date, closed_date_sk, store_name,
   number_employees, floor_space, hours, manager, market_id, geography_class,
   market_desc, market_manager, division_id, division_name, company_id,
   company_name, street_number, street_name, street_type, suite_number,
   city, county, state, zip, country, gmt_offset, tax_precentage, deleted)
SELECT r.id,
       r.store_id,
       r.rec_start_date,
       r.rec_end_date,
       r.closed_date_sk::int,
       r.store_name,
       r.number_employees::int,
       r.floor_space::int,
       r.hours,
       r.manager,
       r.market_id::int,
       r.geography_class,
       r.market_desc,
       r.market_manager,
       r.division_id::int,
       r.division_name,
       r.company_id::int,
       r.company_name,
       r.street_number,
       r.street_name,
       r.street_type,
       r.suite_number,
       r.city,
       r.county,
       r.state,
       r.zip,
       r.country,
       r.gmt_offset::float8,
       r.tax_precentage::float8,
       {{ .operation | eq "delete" }}
FROM {{ .rows }}
ON CONFLICT (id) DO UPDATE SET
  store_id         = EXCLUDED.store_id,
  rec_start_date   = EXCLUDED.rec_start_date,
  rec_end_date     = EXCLUDED.rec_end_date,
  closed_date_sk   = EXCLUDED.closed_date_sk,
  store_name       = EXCLUDED.store_name,
  number_employees = EXCLUDED.number_employees,
  floor_space      = EXCLUDED.floor_space,
  hours            = EXCLUDED.hours,
  manager          = EXCLUDED.manager,
  market_id        = EXCLUDED.market_id,
  geography_class  = EXCLUDED.geography_class,
  market_desc      = EXCLUDED.market_desc,
  market_manager   = EXCLUDED.market_manager,
  division_id      = EXCLUDED.division_id,
  division_name    = EXCLUDED.division_name,
  company_id       = EXCLUDED.company_id,
  company_name     = EXCLUDED.company_name,
  street_number    = EXCLUDED.street_number,
  street_name      = EXCLUDED.street_name,
  street_type      = EXCLUDED.street_type,
  suite_number     = EXCLUDED.suite_number,
  city             = EXCLUDED.city,
  county           = EXCLUDED.county,
  state            = EXCLUDED.state,
  zip              = EXCLUDED.zip,
  country          = EXCLUDED.country,
  gmt_offset       = EXCLUDED.gmt_offset,
  tax_precentage   = EXCLUDED.tax_precentage,
  deleted          = EXCLUDED.deleted
